UPDATE `command` SET `help` = '用法：.tokencap。显示你的账号本小时已获得多少市集代币，以及本小时何时结束。' WHERE `name` = 'tokencap' AND `help` = 'Syntax: .tokencap. Show how many Bazaar Tokens your account has earned this hour and when the hour ends.';
UPDATE `command` SET `help` = '用法：.tokencap set [$玩家] #已获得 [#分钟前]。将该账号设定为本小时已获得 #已获得 个代币，且本小时开始于 #分钟前 分钟前。' WHERE `name` = 'tokencap set' AND `help` = 'Syntax: .tokencap set [$player] #earned [#minutesAgo]. Put the account at #earned tokens in an hour that began #minutesAgo minutes ago.';
UPDATE `command` SET `help` = '用法：.tokencap reset [$玩家]。结束该账号本小时：下一个代币将开启新的小时。' WHERE `name` = 'tokencap reset' AND `help` = 'Syntax: .tokencap reset [$player]. End the account''s hour: its next token opens a new one.';
