UPDATE `creature_text` SET `Text` = '你的族类在主人的世界中没有位置。' WHERE `CreatureID` = 39705 AND `GroupID` = 1 AND `ID` = 0 AND `Text` = 'Your kind has no place in the master\'s world.';
UPDATE `creature_text` SET `Text` = '大地可以被塑造、被模铸……而你不行！你毫无用处！' WHERE `CreatureID` = 39705 AND `GroupID` = 2 AND `ID` = 0 AND `Text` = 'Earth can be shaped, molded... You cannot! You are useless!';
UPDATE `creature_text` SET `Text` = '我无法被摧毁……只是……被……拖延……' WHERE `CreatureID` = 39705 AND `GroupID` = 3 AND `ID` = 0 AND `Text` = 'I cannot be destroyed... Only... de... layed...';
UPDATE `creature_text` SET `Text` = '%s准备与他的一个暗影交换位置！' WHERE `CreatureID` = 39705 AND `GroupID` = 4 AND `ID` = 0 AND `Text` = '%s prepares to trade places with one of his shadows!';
UPDATE `quest_offer_reward` SET `RewardText` = '<芬克的头盔发出静电噼啪声。>$B$B我们时间不多了。拉兹看起来受伤了。如果我们能及时赶到他那里，也许我还有机会把他变回普通的兽人！$B$B<你感到后脑一阵剧痛，并听到钱币的叮当声。>$B$B抱歉。我想着给你送点金币——算是辛苦费什么的……' WHERE `ID` = 28737 AND `RewardText` = '<Finkle\'s helm crackles with static.>$B$BWe haven\'t got much time. Raz looked injured. If we get to him in time there might be a chance that I can turn him back into a regular orc!$B$B<You feel a sharp pain in the back of your head and hear the jingling of coins.>$B$BSorry about that. I figured I\'d send through some gold - for your troubles and all that...';
UPDATE `quest_offer_reward` SET `RewardText` = '<芬克的头盔发出静电噼啪声。>$B$B这下应该能让他们那军械库停摆——至少暂时如此。$B$B拉兹从熔炉另一侧的坡道跑了。快走快走快走！' WHERE `ID` = 28738 AND `RewardText` = '<Finkle\'s helm crackles with static.>$B$BThat should put a stop to their armory - at least for now.$B$BRaz ran off across the ramp on the other side of the forge. GO GO GO!';
UPDATE `quest_offer_reward` SET `RewardText` = '<芬克的头盔发出静电噼啪声。>$B$B呼……要是我们能活着离开这地方，需要操心的事总算少了一件。' WHERE `ID` = 28740 AND `RewardText` = '<Finkle\'s helm crackles with static.>$B$BPhew... That\'s one less thing I\'ll need to worry about if we ever make it out of this place.';
UPDATE `quest_offer_reward` SET `RewardText` = '可怜的拉兹。他是一个侏儒有过的最好的朋友。至少我们为他报了仇，也清空了这座地狱般的洞穴！' WHERE `ID` = 28741 AND `RewardText` = 'Poor Raz. He was the best friend a gnome ever had. At least we avenged his death and cleared out this hellish cavern!';
