UPDATE `coa_client_spell_description` SET `Description` = '|cff66ccff消耗散落星辰|r\r\n射出一支附魔箭矢，造成 $s2% 远程武器伤害，外加 ${$801977m1+$801977ppl1+$POWER1*.09} 点奥术伤害，数值进一步受你的最大法力值加成。$?s500205[\r\n\r\n|cFFFFFFFF月蚀：|r 对目标施加|cffff4500灼烧|r，在 $561122d 内造成 $561122o1 点法术火焰伤害。受到你的|cFFFFFFFF星火术|r影响的敌人无法潜行。][] @s:804716:0@' WHERE `Description` = '|cff66ccffConsumes Scattered Stars|r\r\nFire an enchanted arrow, dealing $s2% Ranged Weapon Damage plus ${$801977m1+$801977ppl1+$POWER1*.09} Arcane damage, scaling further based on your maximum mana.$?s500205[\r\n\r\n|cFFFFFFFFLunar Eclipse:|r |cffff4500Burns|r the target, dealing $561122o1 Spellfire damage over $561122d. Enemies affected by your |cFFFFFFFFStarfire|r cannot stealth.][] @s:804716:0@';
UPDATE `quest_template` SET `LogTitle` = '这是什么地方？', `LogDescription` = '杀死柯尔拉，暮光先驱。', `QuestDescription` = '<芬克的头盔让你轻微一震。>$B$B这是什么地方？他们好像正在对那头虚空龙做可怕的事。能量正从那只生物身上被抽取到那个女人那里！我们必须阻止这个仪式！$B$B杀掉柯尔拉，通过这座大厅！', `QuestCompletionLog` = '与黑石山黑石岩窟内的芬克·恩霍尔交谈。' WHERE `ID` = 28737 AND `LogTitle` = 'What Is This Place?';
UPDATE `quest_template` SET `LogTitle` = '暮光熔炉', `LogDescription` = '杀死卡什·钢锻。', `QuestDescription` = '<芬克的头盔嗡嗡作响。>$B$B该死！拉兹停不下来！就好像他怀着对所有暮光之物的燃烧复仇！看来我们要想通过这个房间追上拉兹，就得干掉那个暮光铸甲师卡什·钢锻。快杀了他，$N。', `QuestCompletionLog` = '与黑石山黑石岩窟内的芬克·恩霍尔交谈。' WHERE `ID` = 28738 AND `LogTitle` = 'The Twilight Forge';
UPDATE `quest_template` SET `LogTitle` = '我眼花了？', `LogDescription` = '杀死美女。', `QuestDescription` = '<芬克的头盔随着一声响亮的少女尖叫炸响。>$B$B不可能！我……我在那种野兽肚子里待了大半个月。对，就是字面意义上卡在它胃里。要不是我的套装和万能头盔，我早就被烧死了！看看，它还生了一窝崽子！$B$B你……你得阻止那东西，$N！我们不能让它或它的崽子活着离开这里！', `QuestCompletionLog` = '与黑石山黑石岩窟内的芬克·恩霍尔交谈。' WHERE `ID` = 28740 AND `LogTitle` = 'Do My Eyes Deceive Me?';
UPDATE `quest_template` SET `LogTitle` = '晋升者领主奥西迪斯', `LogDescription` = '杀死晋升者领主奥西迪斯。', `QuestDescription` = '<芬克的头盔嗡嗡作响。>$B$B天哪！看看这地方！那……天花板上的抓痕是死亡之翼留下的吗？！房间中央那个生物是什么？$B$B我到处都没看到拉兹。我们先解决这个怪物，再去找拉兹！', `QuestCompletionLog` = '与黑石山黑石岩窟内的芬克·恩霍尔交谈。' WHERE `ID` = 28741 AND `LogTitle` = 'Ascendant Lord Obsidius';
